interface CultureBarPipProps extends JSX.HTMLAttributes<HTMLDivElement> {
	pip: CulturePointPip;
	onMountFunc: () => void;
	pipIndex: number;
	ageIndex: number;
	playerIndex: number;
	color: string;
	isWonder?: boolean;
}

interface CultureBarGraphComponents {
	pipList: CulturePipList;
	color: string;
	ageIndex: number;
	playerIndex: number;
	turnPercentages: number[];
	currentAgeProgressPercentage: number;
	isCurrentAge: boolean;
	onHighlightedSegmentDrawn?: (segmentPosition: { left: number; top: number; height: number; width: number }) => void;
}

const MIN_ARC_HEIGHT = 1; // The lowest an arc can be (pips very close together)
const LINEAR_SCALE = 0.38; // Scale the height based on distance wetween pips
const NONLINEAR_SCALE = 0.06; // Little extra bump for larger gaps
const MAX_ARC_HEIGHT = 64; // The heighest an arc can be (pips far apart)

const CultureBarPip: Component<CultureBarPipProps> = (props) => {
	const model = useVictoriesScreenContext();
	const [root, setRoot] = createPropsRefSignal<HTMLElement>(() => props.ref);
	const layoutComplete = createLayoutComplete();

	createEffect(() => {
		if (layoutComplete()) {
			const pipDot = root()?.querySelector("#culture-pip-dot") as HTMLElement;
			if (!pipDot) {
				return;
			}

			const x = root()?.offsetLeft ?? 0;
			const width = root()?.offsetWidth ?? 0;

			//Dot's offset from middle of the pip container
			const pipOffset = pipDot.offsetTop + pipDot.offsetHeight / 4;

			const pips = model.data.cultureDetails.playerDetails[props.playerIndex].allCulturePips[props.ageIndex].pips;

			if (props.pipIndex >= pips.length) {
				return;
			}

			pips[props.pipIndex].location = { x: x + width / 2, y: pipOffset };

			props.onMountFunc();
		}
	});

	const onFocus = () => {
		model.focusPlayer(
			model.data.cultureDetails.playerDetails[props.playerIndex].playerInfo.playerId,
			VictoryTabType.Cultural,
		);
	};
	const onBlur = () => {
		model.unFocusPlayer(
			model.data.cultureDetails.playerDetails[props.playerIndex].playerInfo.playerId,
			VictoryTabType.Cultural,
		);
	};

	return (
		<div
			ref={setRoot}
			class="flex flex-col absolute items-center justify-center h-full pointer-events-auto"
			style={{ left: props.pip.position + "%" }}
		>
			<Tooltip
				initialVPosition={TooltipVerticalPosition.TOP}
				initialHPosition={TooltipHorizontalPosition.CENTER}
			>
				<Tooltip.Trigger>
					<Activatable
						class={`victories-culture-pip relative bg-contain bg-center bg-no-repeat ${props.pip.sources[0].isBig ? "size-16" : "size-14 mb-1 mt-1"}`}
						style={{
							"background-image": props.pip.sources[0].isBig
								? "url(blp:culture_pin_major)"
								: "url(blp:culture_pin_minor)",
							// eslint-disable-next-line solid/style-prop
							"fxs-background-image-tint": props.color,
						}}
						onFocus={onFocus}
						onBlur={onBlur}
					>
						<div
							class={`absolute bg-no-repeat bg-center ${props.pip.sources[0].isBig ? "size-10 top-1 left-3" : "size-7 top-1\\.5 left-3\\.5"}`}
							style={{
								"background-image": props.pip.sources[0].iconSrc,
								"border-radius": "50%",
								// Clip wonder icons a bit more to eliminate the square frames baked into the icon
								"background-size": props.isWonder ? "130% 130%" : "cover",
							}}
						/>
						<Show when={props.pip.sources.length > 1}>
							<div
								class={`absolute ${props.pip.sources[0].isBig ? "size-7 bottom-2 right-2" : "size-5 bottom-4 right-3"} bg-contain bg-center bg-no-repeat pointer-events-none`}
								style={{
									"background-image": "url(blp:victories_culturePlus)",
								}}
							/>
						</Show>
					</Activatable>
				</Tooltip.Trigger>
				<Tooltip.Content>
					<Tooltip.Frame class="relative flex flex-col p-2 items-center justify-center">
						<div class="text-title uppercase text-secondary mb-1">
							<L10n.Compose text={"LOC_VICTORIES_CULTURE_SOURCES"} />
						</div>
						<div class="mb-3">
							<L10n.Compose text={props.pip.ageName} />
						</div>
						<CardFrame class="mb-3">
							<For each={props.pip.sources}>
								{(row, index) => {
									return (
										<>
											<div class="flex flex-row items-center victories-culture-tooltip-body p-1 my-1 w-96 relative">
												<div
													class="size-9 bg-contain bg-no-repeat bg-center ml-2"
													style={{ "background-image": row.iconSrc }}
												/>
												<Divider.Vertical
													margin={2}
													length="13"
												/>
												<div class="flex flex-col justify-center min-h-11 w-64">
													<div class="uppercase text-title">{row.typeName}</div>
													<Show when={row.sourceName != undefined}>{row.sourceName}</Show>
												</div>
												<div class="absolute right-2">{row.points}</div>
											</div>
											<Show when={index() < props.pip.sources.length - 1}>
												<Divider.Horizontal
													class="my-1 ml-2"
													length="84"
												/>
											</Show>
										</>
									);
								}}
							</For>
						</CardFrame>
					</Tooltip.Frame>
				</Tooltip.Content>
			</Tooltip>
			<div
				id="culture-pip-dot"
				class="size-3 mb-1"
				style={{ border: "2px solid black", "border-radius": "50%", "background-color": props.color }}
			/>
			{props.pip.points}
		</div>
	);
};

const CultureBarGraph: Component<CultureBarGraphComponents> = (props) => {
	const model = useVictoriesScreenContext();
	const [allPipsPlaced, setAllPipsPlaced] = createSignal<boolean>(false);

	let canvas: HTMLCanvasElement | undefined;

	onMount(() => {
		if (canvas) {
			createEffect(() => {
				if (!allPipsPlaced()) {
					return;
				}

				const canvasRect = canvas.getBoundingClientRect();
				canvas.width = canvasRect.width;
				canvas.height = canvasRect.height;

				const ctx = canvas.getContext("2d");
				if (!ctx) {
					return;
				}

				ctx.clearRect(0, 0, canvas.width, canvas.height);

				// Layout the age progress percentage segments
				const barTop = canvas.height * 0.1;
				const barHeight = canvas.height * 0.8;
				const segmentWidth = Math.max(canvas.width * 0.008, 1);

				props.turnPercentages.forEach((percentage) => {
					const left = (percentage / 100) * canvas.width;
					const isHighlighted = props.isCurrentAge && props.currentAgeProgressPercentage === percentage;

					ctx.fillStyle = isHighlighted ? "rgba(120, 139, 179, 0.9)" : "rgba(97, 98, 102, 0.6)";
					ctx.fillRect(left, barTop, segmentWidth, barHeight);

					if (isHighlighted && props.onHighlightedSegmentDrawn) {
						props.onHighlightedSegmentDrawn({
							left: canvasRect.left + left,
							top: canvasRect.top + barTop,
							height: barHeight,
							width: segmentWidth,
						});
					}
				});

				// Draw arced lines between the pips
				ctx.strokeStyle = "#616266";
				ctx.lineWidth = 2;

				props.pipList.pips.forEach((_pip, index) => {
					if (index >= props.pipList.pips.length - 1) {
						return;
					}

					const startLoc =
						model.data.cultureDetails.playerDetails[props.playerIndex].allCulturePips[props.ageIndex].pips[
							index
						].location;

					const endLoc =
						model.data.cultureDetails.playerDetails[props.playerIndex].allCulturePips[props.ageIndex].pips[
							index + 1
						].location;

					const startX = startLoc.x + 6;
					const startY = startLoc.y;
					const endX = endLoc.x - 6;
					const endY = endLoc.y;

					const cpX = (startX + endX) / 2;
					const pipDistance = Math.abs(endX - startX);

					//Calculate the arc height based on the distance between the pips
					const arcHeight = Math.min(
						MAX_ARC_HEIGHT,
						MIN_ARC_HEIGHT + pipDistance * LINEAR_SCALE + Math.sqrt(pipDistance) * NONLINEAR_SCALE,
					);

					const cpY = Math.min(startY, endY) - arcHeight;

					drawDashedQuadraticBezier(ctx, startX, startY, cpX, cpY, endX, endY, 6, 4);
				});
			});
		}
	});

	onCleanup(() => {
		if (canvas) {
			canvas.width = 0;
			canvas.height = 0;
		}
	});

	return (
		<>
			<div class="absolute inset-0 pointer-events-none">
				<canvas
					class="size-full"
					ref={canvas}
				/>
			</div>
			<For each={props.pipList.pips}>
				{(pip, index) => {
					return (
						<CultureBarPip
							isWonder={pip.sources[0].isWonder}
							color={props.color}
							pip={pip}
							pipIndex={index()}
							ageIndex={props.ageIndex}
							playerIndex={props.playerIndex}
							onMountFunc={() => {
								if (index() == props.pipList.pips.length - 1) {
									untrack(() => {
										setAllPipsPlaced(true);
									});
								}
							}}
						/>
					);
				}}
			</For>
		</>
	);
};

interface AgeIndicatorProps extends JSX.HTMLAttributes<HTMLDivElement> {
	isCurrentAge: Accessor<boolean>;
	currentAgePercent: number;
	currentProgressSegmentLocation: Accessor<{ left: number; top: number; height: number; width: number } | undefined>;
}

const AgeIndicator: Component<AgeIndicatorProps> = (props) => {
	const [root, setRoot] = createPropsRefSignal<HTMLElement>(() => props.ref);
	const layoutComplete = createLayoutComplete();

	createEffect(() => {
		if (props.isCurrentAge() && layoutComplete()) {
			const location = props.currentProgressSegmentLocation();
			if (!location || root() === undefined) {
				return;
			}

			const parentRect = root()?.parentElement?.getBoundingClientRect();
			if (!parentRect) {
				return;
			}

			//We want to ensure the offset from the top of the bar remains the same through scaling, so we have to use a
			//scaled value here (the height of the segment) as the base
			const scaledOffset = location.height / 12;

			const absoluteTop = location.top - parentRect.top + scaledOffset;
			const absoluteLeft = location.left - parentRect.left + location.width / 2;

			root()!.style.top = absoluteTop + "px";
			root()!.style.left = absoluteLeft + "px";
			root()!.classList.remove("hidden");
		}
	});

	return (
		<Show when={props.isCurrentAge()}>
			<div
				ref={setRoot}
				class="absolute text-xs hidden translate-x-1\/2"
			>
				{props.currentAgePercent.toString() + "%"}
			</div>
		</Show>
	);
};

const CultureVictoryTabComponent: Component<CultureDetailProps> = (props) => {
	const model = useVictoriesScreenContext();
	const [isHighlightingAnyone, setIsHighlightingAnyone] = createSignal<boolean>(false);
	const [isCurrentAge, setIsCurrentAge] = createSignal<boolean>(true);
	const [currentProgressSegment, setCurrentProgressSegment] = createSignal<
		{ left: number; top: number; height: number; width: number } | undefined
	>(undefined);
	const hotkeyContext = useContext(HotkeyContext);

	onMount(() => {
		hotkeyContext.registerNavtray("shell-action-2", "LOC_VICTORY_NAV_HELP_AGE_TOOLTIP");
		hotkeyContext.registerNavtray("shell-action-3", "LOC_VICTORY_NAV_HELP_RULES");
		model.tabNavStartup(hotkeyContext);
	});

	onCleanup(() => {
		hotkeyContext.unregisterNavtray("shell-action-2");
		hotkeyContext.unregisterNavtray("shell-action-3");
		model.tabNavShutdown(hotkeyContext);
	});

	createEffect(() => {
		setIsCurrentAge(model.data.cultureDetails.ageOptions.selectedValue() == Game.age);
	});

	createEffect(() => {
		setIsHighlightingAnyone(
			props.playerDetails.some((player) => {
				return player.playerInfo.highlighted() || player.playerInfo.focused();
			}),
		);
	});

	const iterableItems = createMemo(() => {
		const result: { name: string; description: string; value: AgeType }[] = [];
		for (const [key, value] of props.ageOptions.items.entries()) {
			result.push({ name: value.name, description: value.description, value: key });
		}
		return result;
	});

	function onFocus(playerId: PlayerId) {
		model.focusPlayer(playerId, VictoryTabType.Cultural);
	}

	function onBlur(playerId: PlayerId) {
		model.unFocusPlayer(playerId, VictoryTabType.Cultural);
	}

	return (
		<div class="w-full">
			<VictoryTabBase
				header={model.data.cultureDetails.headerText}
				titleColorClass={model.data.panels[0].titleColor}
				background={model.data.panels[0].background}
				targetScore={model.data.cultureDetails.targetScore}
				title="LOC_VICTORY_CULTURE_MODERN_NAME"
				rules="LOC_VICTORIES_RULES_CULTURE"
				pointsNeededText="LOC_TOURISM_POINTS_NEEDED_TO_WIN"
				preScrollContent={
					<div class="relative flex flex-col self-start items-center w-full">
						<VictoryHeader>
							<div class="relative ml-2 mt-2\.5 uppercase fxs-header self-end">
								<Dropdown
									defaultValue={props.ageOptions.selectedValue()}
									selectedItemTemplate={(value) => (
										<Tooltip initialHPosition={TooltipHorizontalPosition.RIGHT}>
											<Tooltip.Trigger>
												<L10n.Compose text={props.ageOptions.items.get(value)?.name ?? ""} />
											</Tooltip.Trigger>
											<Tooltip.Content>
												<Tooltip.Frame>
													<L10n.Compose
														text={props.ageOptions.items.get(value)?.description ?? ""}
													/>
												</Tooltip.Frame>
											</Tooltip.Content>
										</Tooltip>
									)}
									hotkey="shell-action-2"
									onItemSelected={(selected) => {
										props.ageOptions.setSelectedValue(selected as AgeType);
									}}
								>
									<For each={iterableItems()}>
										{(value) => (
											<Tooltip initialHPosition={TooltipHorizontalPosition.RIGHT}>
												<Tooltip.Trigger>
													<DropdownItem value={value.value}>
														<L10n.Compose text={value.name} />
													</DropdownItem>
												</Tooltip.Trigger>
												<Tooltip.Content>
													<Tooltip.Frame>
														<L10n.Compose text={value.description} />
													</Tooltip.Frame>
												</Tooltip.Content>
											</Tooltip>
										)}
									</For>
								</Dropdown>
							</div>
						</VictoryHeader>
					</div>
				}
			>
				<VSlot
					class="flex flex-col"
					lockNavigation={true}
				>
					<For each={props.playerDetails}>
						{(player, playerIndex) => {
							return (
								<VSlot
									class="transition-opacity duration-150 ease-out victories-cultural-focus"
									classList={{
										"opacity-50":
											isHighlightingAnyone() &&
											player.playerInfo.highlighted() === false &&
											player.playerInfo.focused() === false,
									}}
								>
									<VictoryRow
										rowId={playerIndex() + 1}
										playerInfo={player.playerInfo}
										divider={false}
										rowType={VictoryTabType.Cultural}
										showTooltip={false}
										activateInfo={(playerId: PlayerId) => {
											if (ActionHandler.isTouchActive) {
												model.focusPlayer(playerId, VictoryTabType.Cultural);
												model.onGamepadInspectButton();
											}
										}}
									>
										<div
											class="flex-auto flex flex-row h-32"
											onMouseEnter={() => {
												player.playerInfo.setHighlighted(true);
											}}
											onMouseLeave={() => {
												player.playerInfo.setHighlighted(false);
											}}
										>
											<div class="flex flex-col justify-center">
												<Divider.Vertical
													class="-translate-x-1\/2"
													length="3\/4"
													color="rgba(255, 255, 255, 0.6)"
												/>
											</div>
											<div
												class={"absolute top-0 bottom-0"}
												style={{ left: "1.5%", right: "2%" }}
											>
												<For each={player.allCulturePips}>
													{(pipList, index) => {
														return (
															<Show
																when={pipList.age == props.ageOptions.selectedValue()}
															>
																<CultureBarGraph
																	ageIndex={index()}
																	pipList={pipList}
																	color={player.playerColor}
																	playerIndex={playerIndex()}
																	turnPercentages={props.turnPercentages}
																	currentAgeProgressPercentage={
																		props.currentAgeProgressPercentage
																	}
																	isCurrentAge={isCurrentAge()}
																	//Only showing the progress percentage for the top bar
																	onHighlightedSegmentDrawn={
																		playerIndex() == 0
																			? setCurrentProgressSegment
																			: undefined
																	}
																/>
															</Show>
														);
													}}
												</For>
											</div>
										</div>
										<Tooltip
											initialVPosition={TooltipVerticalPosition.TOP}
											initialHPosition={TooltipHorizontalPosition.CENTER}
										>
											<Tooltip.Trigger>
												<Activatable
													class="victories-focusable-ticket w-22 mt-4 mr-2"
													onFocus={() => onFocus(player.playerInfo.playerId)}
													onBlur={() => onBlur(player.playerInfo.playerId)}
												>
													<CardFrame class="size-24 flex flex-col items-center justify-center self-center opacity-100">
														<div
															class="size-14 bg-center bg-contain bg-no-repeat -mb-2"
															style={{
																"background-image": "url(blp:fonticon_greatwork)",
															}}
														/>
														<div class="text-xl text-title">
															{player.greatWorksData.pointsTotal}
														</div>
													</CardFrame>
												</Activatable>
											</Tooltip.Trigger>
											<Tooltip.Content>
												<Tooltip.Frame class="relative flex flex-col p-2 items-center justify-center">
													<div class="text-title uppercase text-secondary mb-1">
														<L10n.Compose text={"LOC_UI_GREAT_WORKS_TITLE"} />
													</div>
													<CardFrame class="w-84 mb-3">
														<For each={player.greatWorksData.sources}>
															{(source, index) => {
																return (
																	<Show when={source.points > 0}>
																		<div class="flex flex-row items-center w-full p-1 my-1 relative">
																			<div
																				class="size-9 bg-contain bg-no-repeat bg-center ml-2"
																				style={{
																					"background-image": source.icon,
																				}}
																			/>
																			<Divider.Vertical
																				margin={2}
																				length="13"
																			/>
																			<div class="flex flex-col justify-center h-11">
																				<div class="uppercase text-title">
																					<L10n.Compose
																						text={source.typeName}
																					/>
																				</div>
																			</div>
																			<div class="absolute right-2">
																				{source.points}
																			</div>
																		</div>
																		<Show
																			when={
																				index() <
																				player.greatWorksData.sources.length - 1
																			}
																		>
																			<Divider.Horizontal
																				class="my-1 ml-2"
																				length="80"
																			/>
																		</Show>
																	</Show>
																);
															}}
														</For>
													</CardFrame>
												</Tooltip.Frame>
											</Tooltip.Content>
										</Tooltip>
									</VictoryRow>
								</VSlot>
							);
						}}
					</For>
				</VSlot>
			</VictoryTabBase>
			<AgeIndicator
				currentAgePercent={props.currentAgeProgressPercentage}
				isCurrentAge={isCurrentAge}
				currentProgressSegmentLocation={currentProgressSegment}
			/>
		</div>
	);
};

export const CultureVictoryTab = ComponentRegistry.register({
	name: "CultureVictoryTab",
	createInstance: CultureVictoryTabComponent,
});
